examples.template:
MonarchButton({{trigger}}, systemImage: "person.badge.minus", variant: .danger) {
    allTo = nil
    isOpen = true
}
.sheet(isPresented: $isOpen) {
    NavigationStack {
        handOver
            .navigationTitle({{title}})
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button({{cancel}}) { isOpen = false }.disabled(isRemoving)
                }
                ToolbarItem(placement: .confirmationAction) {
                    if isRemoving {
                        ProgressView().accessibilityLabel("Removing {{member.name|raw}}")
                    } else {
                        Button({{continue}}) { isConfirming = true }
                    }
                }
            }
            .confirmationDialog(
                "Remove {{member.name|raw}}?",
                isPresented: $isConfirming,
                titleVisibility: .visible,
                actions: {
                    Button("Remove member", role: .destructive) { remove() }
                    Button("Cancel", role: .cancel) {}
                },
                message: { Text("They lose access to the workspace straight away.") }
            )
    }
    .interactiveDismissDisabled(isRemoving)
}
.monarchToastHost(toasts)

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var toasts = MonarchToastCenter()
@State private var isOpen = false
@State private var allTo: String?
@State private var isPerKind = false
@State private var assignments: [String: String] = [:]
@State private var isConfirming = false
@State private var isRemoving = false
private let work = [
    (id: {{work.0.id}}, count: {{work.0.count}}, label: {{work.0.label}}),
    (id: {{work.1.id}}, count: {{work.1.count}}, label: {{work.1.label}}),
    (id: {{work.2.id}}, count: {{work.2.count}}, label: {{work.2.label}}),
]
private let people = [
    MonarchAssigneePerson(id: {{people.0.id}}, name: {{people.0.name}}, email: {{people.0.email}}),
    MonarchAssigneePerson(id: {{people.1.id}}, name: {{people.1.name}}, email: {{people.1.email}}),
    MonarchAssigneePerson(id: {{people.2.id}}, name: {{people.2.name}}, email: {{people.2.email}}),
    MonarchAssigneePerson(id: {{people.3.id}}, name: {{people.3.name}}, email: {{people.3.email}}),
]

private var target: String? { people.first { $0.id == allTo }?.name }

/// Who takes one kind of work: the person chosen for it, or the one chosen for all work.
private func assignee(of kind: String) -> String? {
    people.first { $0.id == (isPerKind ? assignments[kind] : allTo) }?.name
}

private var handOver: some View {
    ScrollView {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text("Step 1 of 2")
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
                ProgressView(value: 0.5)
                    .progressViewStyle(.monarchLinear)
                    .accessibilityHidden(true)
            }
            Text({{handOver.heading}}).monarchTextStyle(.heading).accessibilityAddTraits(.isHeader)
            Text({{handOver.description}})
                .monarchTextStyle(.body)
                .foregroundStyle(theme.colors.textMuted)
            if isPerKind {
                ForEach(work, id: \.id) { item in
                    MonarchAssigneePicker(
                        item.label,
                        selection: Binding(get: { assignments[item.id] }, set: { assignments[item.id] = $0 }),
                        people: people,
                        currentUserID: {{currentUserId}},
                        showsAssignToMe: false,
                        labels: MonarchAssigneePickerLabels(unassigned: {{handOver.unassigned}})
                    )
                }
            } else {
                MonarchAssigneePicker(
                    {{handOver.reassign}},
                    selection: $allTo,
                    people: people,
                    currentUserID: {{currentUserId}},
                    showsAssignToMe: false,
                    labels: MonarchAssigneePickerLabels(unassigned: {{handOver.unassigned}})
                )
            }
            Toggle({{handOver.perKind}}, isOn: $isPerKind)
                .toggleStyle(.monarchCheckbox)
                .monarchTextStyle(.body)
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                ForEach(work, id: \.id) { item in
                    Text("\u{2022}  \(item.count) \(item.label)")
                        .monarchTextStyle(.body)
                        .foregroundStyle(theme.colors.textMuted)
                }
            }
        }
        .padding(theme.spacing.space4)
    }
    .background(theme.colors.bgCanvas)
}

private func remove() {
    isRemoving = true
    Task {
        // Send the removal and each work item's assignee to the server here.
        isRemoving = false
        isOpen = false
        toasts.show("{{member.name|raw}} removed", actionTitle: "Undo", duration: 8) {
            // Restore the membership and the work on the server.
        }
    }
}

