                MonarchAssigneePicker(
                    "Reassign all open work to",
                    selection: $allTo,
                    people: people,
                    currentUserID: "me",
                    showsAssignToMe: false,
                    labels: MonarchAssigneePickerLabels(unassigned: "Leave unassigned")
